def _notify(self, function_name: str, **kwargs: Any) -> None:
    # For end callbacks, execute in reverse order
    callbacks = reversed(self.callbacks) if function_name.endswith("_end") else self.callbacks
    for c in callbacks:
        try:
            getattr(c, function_name)(**kwargs)
        except Exception as e:
            warnings.warn(
                f"Callback {type(c).__name__}.{function_name} raised {type(e).__name__}: {e}"
            )
